            //
            aIngress = (RotL64(aHeartLaneA[((aIndex + 2000U)) & S_BLOCK1], 23U) ^ RotL64(aHeartLaneB[((aIndex + 3449U)) & S_BLOCK1], 51U));
            aIngress ^= (RotL64(aFireLaneD[((aIndex + 4030U)) & S_BLOCK1], 60U) ^ RotL64(aKeyRowReadB[((aIndex + 5454U)) & W_KEY1], 13U));
