            aWandererI = aWandererI ^ (((RotL64(aPrevious, 57U) + aOrbiterG) + RotL64(aOrbiterA, 47U)) + aTwistWandererUpdateSaltB[(((255U - aIndex) + 194U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aScatter, 30U) + RotL64(aOrbiterF, 38U)) + aOrbiterJ) + RotL64(aCarry, 27U));
            aWandererF = aWandererF ^ ((RotL64(aIngress, 51U) + RotL64(aOrbiterI, 3U)) + aOrbiterC);
            aWandererK = aWandererK + ((RotL64(aCross, 21U) + aOrbiterE) + RotL64(aOrbiterK, 13U));
            aWandererA = aWandererA ^ ((RotL64(aPrevious, 47U) + RotL64(aOrbiterH, 43U)) + aOrbiterA);
