            aOrbiterJ = ((aOrbiterJ + aOrbiterG) + 0x0AF7DB81633B9667ULL) + aKeyRotateAOrbiterUpdateSaltA[(((255U - aIndex) + 203U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterJ) ^ 0x4C9C6358962C73B2ULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 40U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x279346EE244C8359ULL), 23U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0xAB478E84065D32DAULL;
