            //
            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0x81782B956F90B49CULL) + aKeyRotateBOrbiterUpdateSaltA[((aIndex + 189U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0xD1578975CF69A02BULL;
